<template>
  <div class="app-container">
    <p v-if="!embedded" class="hint">{{ business ? '资金结果以平台事实为准；货物处理单独跟踪。平台已退款，不代表已停止发货或商品已退回。' : '保留推送库退款原文与版本，再转 OMS 退款单。转单失败仍暂停相关订单新增履约。' }}</p>
    <el-tabs v-if="business" v-model="disputeTab" @tab-click="search"><el-tab-pane label="全部" name="ALL"/><el-tab-pane label="仅退款" name="REFUND"/><el-tab-pane label="退货退款" name="REFUND_AND_RETURN"/></el-tabs>
    <el-form inline size="small" @submit.native.prevent="search">
      <el-form-item label="单号"><el-input v-model="query.number" clearable :placeholder="business ? 'TK / SO / 平台退款、订单、子单号' : '平台退款 / 订单 / 子单号'" style="width:330px" @keyup.enter.native="search" /></el-form-item>
      <el-form-item v-if="!embedded" label="店铺"><el-select v-model="query.channelId" clearable filterable placeholder="全部店铺"><el-option v-for="c in channels" :key="c.channel_id" :value="c.channel_id" :label="c.channel_name" /></el-select></el-form-item>
      <el-form-item :label="business ? '处理状态' : '转单状态'"><el-select v-model="query.state" clearable><el-option v-for="v in states" :key="v" :value="v" :label="label(v)" /></el-select></el-form-item>
      <el-form-item><el-button type="primary" icon="el-icon-search" @click="search">查询</el-button><el-button @click="reset">{{ embedded?'清除本类筛选':'重置' }}</el-button></el-form-item>
    </el-form>
    <div class="toolbar"><span>{{ business ? '审核用途与货物方案，保留原订单和执行依据' : '按店铺读取 jdp_tb_refund；补拉不改变自动游标' }}</span><div><el-button v-if="business" v-hasPermi="['order:refund:config']" size="small" @click="openReturnRules">退货规则</el-button><el-button v-if="!business" v-hasPermi="['order:refund:sync']" size="small" type="primary" @click="openSync">补拉退款</el-button><el-button v-hasPermi="['order:refund:sync']" size="small" @click="openTasks">同步任务</el-button><el-button size="small" icon="el-icon-refresh" @click="load">刷新</el-button></div></div>
    <el-table v-loading="loading" :data="rows" empty-text="暂无退款记录；请检查退款接入设置或创建补拉任务">
      <el-table-column :label="business ? '业务退款 / 原订单' : '平台退款 / 原订单'" min-width="265"><template slot-scope="s"><el-button type="text" @click="open(s.row.id)">{{ business ? s.row.refund_sn : s.row.refund_id }}</el-button><el-tag v-if="business" size="mini">{{ label(s.row.dispute_type) }}</el-tag><el-tag v-if="business&&Number(s.row.shared_return)" size="mini" type="warning">合包退回</el-tag><div v-if="business">平台退款 {{ s.row.refund_id }}</div><div class="hint">平台订单 {{ s.row.platform_tid }}</div><div class="hint">平台子单 {{ s.row.platform_oid }}</div><div v-if="business" class="hint">OMS {{ s.row.order_sn }}</div></template></el-table-column>
      <el-table-column label="渠道 / 店铺" min-width="180"><template slot-scope="s">天猫 · {{ shop(s.row.channel_id) }}<div class="hint">渠道 ID {{ s.row.channel_id }}</div></template></el-table-column>
      <el-table-column label="申请金额" width="125"><template slot-scope="s"><strong>¥ {{ Number(s.row.refund_fee).toFixed(2) }}</strong><div v-if="!business" class="hint">{{ label(s.row.dispute_type) }} · {{ label(s.row.source_phase) }}</div></template></el-table-column>
      <el-table-column v-if="!business" label="平台退款状态" min-width="170"><template slot-scope="s"><el-tag size="small" :type="s.row.platform_status==='SUCCESS' ? 'success' : 'info'">{{ s.row.platform_status==='SUCCESS' ? '退款成功' : label(s.row.platform_status) }}</el-tag></template></el-table-column>
      <el-table-column v-if="business" label="用途 / 货物方案" min-width="180"><template slot-scope="s">{{ label(s.row.purpose) }}<div class="hint">{{ label(s.row.goods_action) }}</div></template></el-table-column>
      <el-table-column v-if="business" label="资金 / 货物" min-width="180"><template slot-scope="s"><div>资金：{{ s.row.funds_state === 'SUCCESS' ? '平台已退款' : label(s.row.funds_state) }}</div><div>货物：{{ label(s.row.goods_state) }}</div><div v-if="(s.row.parcel_issues||[]).length" class="warning"><el-tag size="mini" type="warning">{{ s.row.parcel_issues[0].title }}</el-tag><div>{{ s.row.parcel_issues[0].reason }}</div></div><div v-if="(s.row.parcel_followups||[]).length" class="hint">{{ s.row.parcel_followups[0].title }}</div><div v-if="Number(s.row.shared_return)&&s.row.goods_state==='WAIT_CHECK'" class="warning">关联包裹实收／回传待核对，已确认数量不含待核对部分</div><div v-if="s.row.return_progress" class="hint">本TK计划 {{ s.row.return_progress.return_quantity }} · 已确认实收 {{ s.row.return_progress.accepted_quantity }} · 入账 {{ s.row.return_progress.posted_quantity }} 件</div></template></el-table-column>
      <el-table-column :label="business ? '审核与处理' : '来源与转单'" min-width="250"><template slot-scope="s"><el-tag size="small" :type="problem(s.row) ? 'warning' : 'info'">{{ label(business ? s.row.state : s.row.conversion_state) }}</el-tag><span class="hint"> {{ label(business ? s.row.review_state : s.row.source_state) }}</span><div class="warning">{{ s.row.problem_message || s.row.source_error || s.row.conversion_error }}</div><div v-if="!business" class="hint">最近同步 {{ s.row.last_sync }}</div></template></el-table-column>
      <el-table-column label="操作" fixed="right" :width="embedded?220:business?310:140"><template slot-scope="s"><el-button v-if="business&&(s.row.parcel_issues||[]).length" v-hasPermi="['order:refund:goods']" type="text" @click="open(s.row.id,true)">处理合包问题</el-button><el-button v-hasPermi="['order:refund:query']" type="text" @click="open(s.row.id)">详情</el-button><el-button v-if="business&&Number(s.row.shared_return)" v-hasPermi="['order:refund:query']" type="text" @click="open(s.row.id,false,true)">查看退回包裹</el-button><el-button v-if="embedded" type="text" :disabled="!s.row.platform_tid" @click="$emit('related',s.row)">原单关联</el-button><el-button v-if="!business && !s.row.business_refund_id" v-hasPermi="['order:refund:convert']" type="text" @click="convert(s.row)">{{ s.row.conversion_state === 'FAILED' ? '重试转单' : '转单' }}</el-button></template></el-table-column>
    </el-table>
    <pagination v-show="total>0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="load" />
    <refund-detail ref="detail" :business="business" @changed="load" />
  </div>
</template>
<script>
import * as api from '@/api/order/refund'
import { label } from './refundLabels'
import RefundDetail from './RefundDetail'
import { platformDocumentList } from '@/api/order/platformDocuments'
const initialQuery = () => ({ number: '', disputeType:'', channelId: '', state: '', pageNum: 1, pageSize: 20 })
export default { name: 'RefundList', components: { RefundDetail }, props: { business:Boolean,embedded:Boolean,sharedFilters:{type:Object,default:()=>({})},shopOptions:{type:Array,default:()=>[]},recordId:{type:Number,default:0} }, data: () => ({ query: initialQuery(), rows: [], total: 0, sequence:0, channels: [], loading: false, saving: false, syncVisible: false, tasksVisible: false, tasks: [], form: {}, range: [], itemsVisible: false, items: [] }), watch: { '$route.query.id'(id) { if (!this.embedded&&id) this.open(Number(id)) },sharedFilters(){if(this.embedded){this.query.pageNum=1;this.load()}},recordId(id){if(this.embedded&&id)this.open(id)} }, computed: { disputeTab:{get(){return this.query.disputeType||'ALL'},set(v){this.query.disputeType=v==='ALL'?'':v}},states() { return this.business ? ['NEEDS_REVIEW', 'PROCESSING', 'BLOCKED', 'COMPLETED', 'CLOSED'] : ['WAITING', 'FAILED', 'SUCCESS', 'SKIPPED'] } }, async created() { this.channels=this.embedded?this.shopOptions:(await api.refundCatalog()).data; this.query.number = this.$route.query.number || ''; await this.load(); if(this.embedded){if(this.recordId)this.open(this.recordId)}else if(this.$route.query.id)this.open(Number(this.$route.query.id)) }, methods: {
  label, shop(id) { const c = this.channels.find(c => Number(c.channel_id) === Number(id)); return c ? c.channel_name : `渠道 ${id}` }, problem(r) { return !!(r.problem_message || r.source_error || r.conversion_error || (r.parcel_issues||[]).length) },
  async load() { const seq=++this.sequence; this.loading = true; try { const r = (await (this.embedded?platformDocumentList('REFUND',{...this.query,...this.sharedFilters}):api.refundList(this.business,this.query))).data; if(seq===this.sequence){this.rows = r.rows; this.total = Number(r.total)} } finally { if(seq===this.sequence)this.loading = false } }, search() { this.query.pageNum = 1; this.load() }, reset() { this.query = initialQuery(); this.load() }, open(id,issue=false,parcel=false) { this.$refs.detail.open(id,issue,parcel) },
  async convert(r) { const result = (await api.convertRefund(r.id)).data; if (result.state === 'SUCCESS') this.$message.success('已转业务退款单'); else this.$message.warning(result.message || label(result.state)); await this.load() },
  openReturnRules() { this.$router.push({path:'/oms-order/afterSaleRules/returns',query:this.query.channelId?{channelId:this.query.channelId}:{}}) },
  openSync() { this.$router.push({path:'/oms-order/management',query:{kind:'REFUND',action:'backfill',...((this.embedded?this.sharedFilters.channelId:this.query.channelId)?{channelId:this.embedded?this.sharedFilters.channelId:this.query.channelId}:{})}}) },
  openTasks() { this.$router.push({path:'/oms-order/management',query:{kind:'REFUND',tab:'tasks',...((this.embedded?this.sharedFilters.channelId:this.query.channelId)?{channelId:this.embedded?this.sharedFilters.channelId:this.query.channelId}:{})}}) }

} }
</script>
<style scoped>.hint{font-size:12px;color:#8290a4;line-height:1.8}.toolbar{display:flex;justify-content:space-between;align-items:center;margin:12px 0 20px;color:#738198}.warning{color:#b77515;line-height:1.8}.el-table .el-button{white-space:normal;word-break:break-all;text-align:left}h3{margin-top:0}</style>
